(function(root){
const statuses=['New','Assigned','Under Investigation','Pending Clarification','Resolved','Closed'];
const transitions={New:['Assigned','Under Investigation'],Assigned:['Under Investigation','Pending Clarification'], 'Under Investigation':['Assigned','Pending Clarification','Resolved'],'Pending Clarification':['Under Investigation','Resolved'],Resolved:['Under Investigation','Closed'],Closed:['Under Investigation']};
function permitted(actor){if(!actor||actor.role==='Auditor')throw Error('This demo role has view-only investigation access.')}
function now(){return new Date().toISOString()}
function event(item,actor,action,detail){item.timeline.push({at:now(),actor:actor.name,action,detail})}
function initial(){return {next:1,cases:[],feedback:{}}}
function find(store,key){return store.cases.find(c=>c.sourceId===key)}
function create(store,actor,source){permitted(actor);let existing=find(store,source.id);if(existing)return existing;let c={id:'INV-'+String(store.next++).padStart(4,'0'),sourceId:source.id,source:source.source,title:source.title,account:source.account,branch:source.branch,category:source.category||'Reconciliation',amount:source.amount,severity:source.severity||'Medium',status:'New',owner:'',dueDate:'',createdAt:now(),updatedAt:now(),resolution:'',notes:[],evidence:source.evidence||[],timeline:[]};event(c,actor,'Case created','Linked to '+source.id+' · '+source.source);store.cases.push(c);return c}
function assign(store,actor,id,owner,dueDate){permitted(actor);let c=store.cases.find(x=>x.id===id);if(!c)throw Error('Case not found.');if(!owner||!/^\d{4}-\d{2}-\d{2}$/.test(dueDate)||!Number.isFinite(Date.parse(dueDate))||new Date(dueDate).toISOString().slice(0,10)!==dueDate)throw Error('Select an investigator and target date.');if(c.status==='Closed')throw Error('Reopen the case before reassigning it.');let previous=c.owner||'Unassigned';c.owner=owner;c.dueDate=dueDate;if(c.status==='New')c.status='Assigned';c.updatedAt=now();event(c,actor,'Investigator assigned',previous+' → '+owner+' · target '+dueDate);return c}
function note(store,actor,id,text){permitted(actor);let c=store.cases.find(x=>x.id===id);if(!c)throw Error('Case not found.');if(!text.trim())throw Error('Enter an investigation note.');c.notes.push({at:now(),actor:actor.name,text:text.trim()});c.updatedAt=now();event(c,actor,'Note added',text.trim());return c}
function change(store,actor,id,status,resolution){permitted(actor);let c=store.cases.find(x=>x.id===id);if(!c||(transitions[c.status]||[]).includes(status)===false)throw Error('That status transition is not available.');if(status==='Assigned'&&(!c.owner||!c.dueDate))throw Error('Save an investigator and target date before assigning.');if(['Resolved','Closed'].includes(status)&&!(resolution||'').trim())throw Error('Record a resolution rationale before resolving or closing.');let previous=c.status;c.status=status;if(resolution?.trim())c.resolution=resolution.trim();c.updatedAt=now();event(c,actor,status==='Under Investigation'&&['Resolved','Closed'].includes(previous)?'Case reopened':'Status changed',previous+' → '+status+(resolution?.trim()?' · '+resolution.trim():''));return c}
function review(store,actor,sourceId,status,reason){permitted(actor);if(!['Reviewed','False Positive'].includes(status)||!reason.trim())throw Error('Select a review decision and provide a rationale.');let previous=store.feedback[sourceId]||null,entry={status,reason:reason.trim(),actor:actor.name,at:now(),history:[...(previous?.history||[]),{status,reason:reason.trim(),actor:actor.name,at:now()}]};store.feedback[sourceId]=entry;let c=find(store,sourceId);if(c){event(c,actor,'Anomaly feedback',status+' · '+reason.trim());if(status==='False Positive'){let from=c.status;c.status='Closed';c.resolution='False positive: '+reason.trim();event(c,actor,'Case closed',from+' → Closed · false positive decision');}c.updatedAt=now();}return entry}
function overdue(c,today){return !!c.dueDate&&c.dueDate<today&&!['Resolved','Closed'].includes(c.status)}
root.Investigations={statuses,transitions,initial,find,create,assign,note,change,review,overdue};if(typeof module!=='undefined')module.exports=root.Investigations;
})(globalThis);
